#ifndef SOUND_DATA_H
#define SOUND_DATA_H
#include <gb/gb.h>
/* generated by tools/make_sound.py: the tunes (bank 7, and bank 42 for the ones with a bank number) */
enum { MUS_TITLE, MUS_PLANET, MUS_DUNGEON, MUS_SPACE, MUS_BOSS, MUS_ENDING, MUS_P_DESERT, MUS_P_ICE, MUS_P_JUNGLE, MUS_P_OCEAN, MUS_P_DUSK, MUS_D_DESERT, MUS_D_ICE, MUS_D_JUNGLE, MUS_D_OCEAN, MUS_D_DUSK, MUS_KART, MUS_WAR, MUS_P_MESA, MUS_P_FUNGAL, MUS_P_CRYSTAL, MUS_P_LAVA, MUS_P_SWAMP, MUS_P_CANDY, MUS_D_MESA, MUS_D_FUNGAL, MUS_D_CRYSTAL, MUS_D_LAVA, MUS_D_SWAMP, MUS_D_CANDY, MUS_TOWN, MUS_STATION, MUS_ALERT, MUS_KART2, MUS_KART3, MUS_KART4, MUS_SHOP, MUS_CAMP, MUS_N };
typedef struct { const UINT8 *mel, *bas, *drm; UINT8 tempo, vol, mask, bank; } SndTrack;   /* mask: the last step (63 or 255); bank: 0 = the data is in bank 7 */   /* drm: 0 none, 1 kick, 2 snare, 3 hat */
extern const UINT16 snd_sq[128];   /* MIDI note -> square-channel frequency register */
extern const UINT16 snd_wv[128];   /* MIDI note -> wave-channel frequency register */
extern const SndTrack snd_tracks[MUS_N];
#define MUS_PLANET_K(k) ((k) >= 6 ? MUS_P_MESA + (k) - 6 : (k) ? MUS_P_DESERT + (k) - 1 : MUS_PLANET)    /* the tune of world kind k (0 garden .. 11 candy) */
#define MUS_DUNGEON_K(k) ((k) >= 6 ? MUS_D_MESA + (k) - 6 : (k) ? MUS_D_DESERT + (k) - 1 : MUS_DUNGEON)
#endif
